style.css:
@-moz-document domain("roblox.com") {
/* This sets your custom wallpaper */
  body, .dark-theme, .light-theme {
    background-image: url("https://ibb.co/N0Qw1wB") !important;
    background-size: cover !important;
    background-attachment: fixed !important;
    background-position: center !important;
  }

  /* This makes the Roblox boxes see-through so you can see your art */
  .content, .section-content, .container-main {
    background-color: rgba(0, 0, 0, 0.5) !important;
    border-radius: 10px !important;
  }
}
